from author_library import *
cards=[]
c=compact('cheng_gong','成功','成功以财富和谜题进入卫斯理的视野，脑后却藏着一个旁人看见就惊恐的面孔。她并不是被怪脸逼得幻想出另一个人：勒曼医院确认两副完整脑部各有活动，又以少量组织相连，共用身体感觉。她的连体伙伴能感应别人部分想法，再把信息传给她，两脑共同活动时出现异常强烈的能量。她不愿以对方死亡换取所谓正常，也不愿让对方只剩孤立脑部靠设备活着；复制实验仍复制出畸形，显示这并非普通整形问题。她早于江海和白老大解开宝库隐语，取得大量财产，以此获得资源和与勒曼医院接触的机会。后来知道自己属于爱神星实验留下的半地球人，她既不安也愤怒，却没有接受用自己基因创造另一批人造脑、预先消灭可能成为威胁的新生命的计划。她认真追问预防灾难能否成为灭绝生命的理由，并转而寻求让同类组成五十五十俱乐部，以继续了解和预防而非预先扑杀面对未来。终局畸形未证实消除，她的力量、钱和伙伴也不应被分成两套重复计算的资产。','《一半一半》保留连体形态，筹建五十五十俱乐部；没有已完成的巫术变形或人造脑军团',['主角','阶段性对立者'],'找到能让自己与伙伴共同生活的方式，保护不同生命的自主权','以聪明的调查和资金取得资源，也认真解释自己的身体与人格','别人要牺牲伙伴或预先消灭新生命时，拒绝用简单的正义口号替代判断','不能以一种扑杀生命代替另一种扑杀，并要求合作建立在真实同意上',[ab('双脑连接与有限感应','连体伙伴感应他人部分想法，经相连脑部共享；合并活动可显著增强脑波','不能保证读取全部思想，极限未知；两张卡共用一个身体和同一份能量，不能相加',kind='脑能量'),ab('推理与资源运用','解开宝库密码并把取得的财富用于寻求医疗与组织同类','财富不是个人物理火力，产权、交易和可调度资源仍须具体交代')],[ev('139',518,617,'拒绝牺牲同伴、两脑连接和实际感应'),ev('139',579,586,'独立破解宝库并联系医院'),ev('139',1149,1189,'拒绝预先扑杀人造脑'),ev('139',1344,1383,'俱乐部、财富和未消除的怪脸')],profile='expert',extra={'baseline':{'energy':'具异常脑活动能量，实证主要是有限感应，不等于能量炮。','mind':'同体两脑共享感觉与思想，能感应他人一些想法；不能视为全知或免控。'},'appearance':{'description':'女性，脑后另有不完整面孔，常以头巾或风帽遮掩；终局没有确认外形被修复。','portrayal':'可以机敏调侃，也会因身份被否定而苦涩；向善意倾听者逐步坦白。'}})
rate(c,[1,2,1,3,2,3],neg=(2,2,2),tier='并',reason='战斗实证有限，主要为相连双脑的局部感应和推理；财富及假设中的未来人造脑不计输出。');cards.append(c)
c=compact('chenggong_other','成功的连体伙伴','他在别人眼里先是一张长在成功脑后的怪脸，面部动作甚至被卫斯理本能地理解成邪恶的讥笑。但真实的他有完整的脑部、独立思想与语言能力，只因发声器官不充分而无法直接说话。他与成功共享一个身体，靠她的神经接收视觉和其他感觉，也把自己的感应传给她。与外观造成的恐惧相反，他曾同意切除自己，让成功不必顾虑他的死活；成功拒绝了这种牺牲。后来医院提出把成功的脑移进复制体、把原身体留给他，两人共同指出那会夺去他通过成功脑部获得的一切感觉；只有在医生提出接通神经的可能后，他们才愿尝试，实验却仍失败。他的脑活动能力高于成功，联合时又增强，但书中没有给出可任意支配人心的实战上限。终局他仍与成功共存，成为她拒绝以他者死亡换取正常生活的最亲近理由。演绎时可让他经成功转述或在双方同意的内部交流中表达分歧，不能把他的怪相写成天生反派，也不能给这个没有独立身体的人另配一套行动次数、财富和装备。','《一半一半》仍作为与成功相连的独立人格存在，没有独立身体','主角','与成功共同生存，并维护双方人格而非仅保住一副外形','通过两脑联系表达意见，借成功感觉接触外界','涉及分离和身体选择时愿意考虑牺牲，但也能指出方案将毁掉自己的感觉生活','外形不是道德证据，双方都必须被当作有意愿的生命',[ab('相连脑部的交流和感应','独立脑活动连接成功脑部，能感应他人部分思想并共享给成功','没有独立感官和发声器官；离开连接会失去感觉，不能单独行动',kind='脑能量')],[ev('139',529,553,'独立思想、发声限制和愿意牺牲'),ev('139',566,617,'感应来源、双脑增强和分离困难'),ev('139',1377,1383,'最终仍有脑后面孔')],extra={'baseline':{'destruction':'没有独立肢体，不能另作一次肉体攻击。','durability':'依附同一身体与相连脑部，不能因独立人格获得第二条独立生命条。','speed':'移动随成功身体，脑活动速度不能当跑速。','energy':'与成功共享同一双脑能量表现，不重复叠加。','mind':'可有限感应他人思想，与成功互相开放；不证明普遍读心或心控免疫。','stamina':'依赖成功的身体和相连神经，无法独立供给。'},'appearance':{'description':'成功脑后的不完整面孔和脑部，面部可作表情，缺少能独立发挥作用的正常感官、发声器官。','portrayal':'主要通过成功转述，表情不能自动当作恶意证据。'},'adaptations':[{'change':'内部对白可由独立人格生成，再由成功决定是否向外转述。','reason':'表现两个人格的同意与分歧，避免只把他当作外观标签。','power_impact':'没有新增外部发声、独立身体或额外能量。'}]})
rate(c,[0,2,1,2,2,1],neg=(4,3,1),tier='纸',reason='有有限感应而没有独立感官身体；与成功共用能量和身体，不能作为第二个独立战斗单位。');cards.append(c)
c=compact('yan_shi','岩石','岩石是叙述者替一位富有探险者使用的假名。他原本在家族财团中有重要地位，却更喜欢深入蛮荒，与岛上猎头族交往并学习他们的语言。一次失踪令家族动员庞大搜寻，外界认定他已死；多年后，他却突然坐进陶启泉安排的聚会，讲述一处难以再找到的地方。那里的人与生活使他觉得人间经验贫乏，离开以后，财富与通常的享乐都不能代替再回去的愿望。他的伴侣高兴想让他把这一切当作妄想，免去徒劳追寻的痛苦，他却认为失望不会再夺去什么，希望至少可能带来新的所得。红绫的调查和长老提出的微缩解释给了他新的理解，但并没有找到可靠入口。《须弥芥子》末，他留下遗书，再从当年坠落的悬崖跳下，尸体未被找到。小说没有确认他回到理想之地，也没有确认微缩机制，因此卡片不能把这一行为当作成功的传送术。若要继续演绎，采用跳崖前最后能沟通行动的状态，保留他在理想回忆与眼前关爱之间的矛盾，绝不把冒死重演事故写成可保证获得幸福的办法。','《须弥芥子》留下遗书后跳崖，失踪且结果未明；部署取最后可行动探险者形态','主角','找回亲历过的理想生活，理解自己经历究竟通向何处','详细讲述难忘经验，凭探险习惯寻路与求证','希望被否定时仍会坚持，但也会因长期无果而痛苦失控','不能把一次奇遇复制成有保证的方法，对未知必须保留未决结局',[ab('探险与地方语言','多年在岛屿山区探险，能与所接触族群交流','年长有身体限制，巨资搜索也无法保证找到异常地点'),ab('特殊经历证词','记得在奇异地方的生活，可以提供调查线索','经历不等于能随意出入或掌握微缩技术')],[ev('142',118,155,'化名、财富背景、探险与失踪'),ev('142',1159,1189,'与高兴的分歧和继续寻找'),ev('143',1297,1351,'微缩仅为解释、跳崖失踪无确认结果')],profile='ordinary',extra={'adaptations':[{'change':'部署为跳崖前最后可行动的老人，保留后续失踪是未知结局的认识。','reason':'不伪造成功归返或复活，让角色可以继续面对选择。','power_impact':'无传送、重生或微缩能力。'}],'uncertainties':['真实姓名未披露，不映射现实身份。','最后跳崖没有回到理想世界的证据。']});cards.append(c)
c=compact('gao_xing','高兴','高兴是随岩石来到聚会的年轻猎头族女子，她的态度强硬，常把一屋子见惯怪事的人说得无言。她看起来像是缺少科学想象力，不懂另一空间，也不愿接受那些令人惊叹的解释；真正的用意却与岩石有关。她看见他一次次因寻找理想地方而痛苦，宁愿让他相信旧经历只是一场妄想，好把剩下的日子留给眼前生活。别人越肯定那地方真实，她就越生气，因为那会使她劝他放下的努力白费。她不是没有感情的怀疑者，岩石抱头颤抖时，她拍拍他的背，再转身要求其他人不要继续给他不切实际的希望。红绫愿意调查，私下向她说了些话，她才改变反应；话的内容没有披露，不能编成已签下某种保证。后来众人接受微缩解释，岩石仍独自跳崖，留下没有证实的去向，高兴的愿望也没有被故事明确实现。她适合在新场景里代表具体照顾者的尺度：先看一个人的真实痛苦，再问宏大的解释能不能帮上忙。族群背景不自动赋予她缩头术或杀人技能，直率与陌生知识也不等于愚蠢。','《须弥芥子》听到微缩解释；岩石后来失踪，她的后续生活未交代','重要配角','让岩石从徒劳追寻中得到实际安宁','用直接话语追问一个解释到底能不能改善眼前处境','所关心的人因空泛希望痛苦时，会当面打断甚至指责权威','照顾必须顾及当事人的愿望，她的保护也可能与对方自主冲突',[ab('陪伴与文化交流','熟悉岩石处境，能够直接表达并影响他与他人的讨论','未证实拥有猎头或缩头技能，不按族群身份自动配置战斗能力')],[ev('142',1155,1189,'反对空泛希望的照顾动机与红绫沟通'),ev('143',1346,1351,'接受解释后岩石仍失踪')],extra={'appearance':{'description':'年轻的猎头族女子；原文没有足够依据统一装备为战士装束。','portrayal':'说话直截了当，发怒时面对众人也不退让；照顾岩石时有轻拍背部的细致动作。'}});cards.append(c)
c=compact('wang_lian','王莲','王莲以主任身份处理人与组织之间最隐秘的接触，她外表与言行可以使谈话显得亲切，真正的目的却藏在信息安排里。《非常遭遇》中，她利用伍路元曾两度因梦脱险的经验，与其担任部长的孙子合作，设计第三个梦的说法，把一个贪官的死刑同全族安危、放射性资源合作联系起来。事情完成得太快，卫斯理和白素看穿时已经无法改变协议；她还留下署名普通、又令人联想到奇异植物的信，使自己的形象更难捉摸。后来光辉的事件中，她又把青年处境包装成需要救人的故事，动用窃听与接近卫宅的手段，试图找到逃离实验计划的人。她与光辉亲近，对其家庭也有了解，却未因此提供全部真相；言王后来指责她多此一举，显示她并非知道所有计划和掌握全部权力的人。终局她仍是能够调动组织渠道的行动者，没有成为读取思想或制造虚拟人的科学家。卡片要让她在任务、私人理解和组织忠诚间采取具体策略，不必每次都笑着背阴谋，也不能让她的伪装自动支配所有人的判断。','《死去活来》仍参与寻找光辉的行动，计划关键内容后来由言王揭示',['重要配角','反派'],'以组织任务为优先，通过关系和信息安排达成结果','让对方在熟悉的语言、关系和利益中接受自己设计的选择','布局受质疑时保留关键事实，转向其他接近渠道或上级协调','她相信达到任务结果比完整告知更重要，但信息优势并非永远可靠',[ab('社会工程与谈判布局','利用当事人记忆、亲属信任、政治承诺和时机诱导同意','需要真实资源与合作者；不是真正造梦、预言或精神控制'),ab('情报接近与监视','能够安排窃听、访问并接触任务相关人物','技术和组织需实际部署，可能被发现；不自动知道光辉全部想法')],[ev('141',1215,1279,'与部长共同设计第三个梦及签订协议'),ev('141',1286,1295,'身份与署名'),ev('144',212,226,'光辉家庭与她所知的边界'),ev('144',1239,1245,'言王揭示其编故事和窃听')],profile='investigator',aliases=['王主任']);cards.append(c)
c=compact('guang_hui','光辉','光辉从小受到组织照顾，父母忙于地质工作，连家庭也不知道他脑中被放进微小芯片。他原本只是秘密实验选中的幼儿之一，成年后才得知脑活动被持续接收、转成电脑数据，甚至形成会自己产生新资料的虚拟脑。这份计算机中的对应物并不等于已经能读出的思想，研究者和他本人都无法解读。他知道情况后，一度愿继续配合研究，把自己作为实验对象，表现出对科学和公共目的的信任。计划随后提出更激烈的一步：先使他的肉体死亡，再让虚拟人体和虚拟脑结合，期望在电脑中诞生新形式生命。纸面的重生并没有经过验证，牺牲却是真实且不可逆的，光辉最终选择逃走，通过反复转发的电子邮件寻求卫斯理或白素的意见。他不是已经成功活在网络中的电子神，而是一个想在决定生死以前听见不同声音的年轻人。故事终局仍不知他的下落，求助邮件继续流传。参战采用尚活着、已知实验真相的状态，允许他在合作愿望与身体自主之间重新作判断，不把拒绝赴死当作怯懦，也不替他完成尚不存在的上传。','《死去活来》逃离计划后失踪，尚无成为虚拟人的证据；采用最后已知活人状态','主角','保留决定自己生命形式的权利，找到可信赖的意见','愿了解实验并合作，在关键选择前寻求不同来源的解释','被要求以死亡验证未证实的重生时，逃离控制并向外求助','研究价值不能取代知情同意，虚拟脑数据不保证自己能复活',[ab('脑电波放大与记录','植入芯片使其脑活动能量被专门仪器接收并记录为数据','这使他被采集而非能攻击别人；本人不能解读全部记录，更未能控制网络',kind='被植入技术'),ab('电子求援','用电子邮件传播求助消息','收件人可能忽略或删除，不能保证安全接触目标')],[ev('144',42,42,'求救邮件'),ev('144',1200,1241,'芯片实验、唯一持续成功记录与本人知情'),ev('144',1254,1262,'不能解读但愿继续配合'),ev('144',1297,1311,'逃亡缘由'),ev('144',1385,1386,'下落仍不明')],extra={'baseline':{'energy':'植入芯片仅放大可被接收的脑活动信号，未演示攻击输出。','mind':'隐私曾被记录，无法解读并不构成心灵防御；记录亦非确定的独立灵魂。'}});cards.append(c)
c=compact('yan_wang','言王','言王是军事科技机构真正掌握权力的上将，却并不以院长名义出现。他与戈壁、沙漠相熟，面对卫斯理的敌意时，使用近乎天真活泼的坦率，把组织如何集中权力的事实直接说出来，使对方一时难以按习惯应付。他负责的秘密计划在幼儿脑中植入芯片，用长期跟踪取得脑活动资料，希望把人的思想变成电脑里的虚拟脑；大多数实验失败，只有光辉持续提供有效信号。即使如此，他们仍无法解读数据，更无法证实毁掉肉体以后可以使人在计算机中重生。言王却把光辉的牺牲视为有价值的任务，想通过卫斯理找到逃走的青年并促成计划。卫斯理反过来建议他自己承担风险，他被忠于组织、开创新生命的愿景打动，表态愿意尝试；小说没有交代实验真正完成。这个终局保留了他的自我献身愿望，也不能替他消除强迫他人承担风险的责任。参战版本是有组织权力和项目知识的人类将领，非已经进入所有计算机、能操纵导弹的虚拟统治者。','《死去活来》表态愿亲自尝试虚拟化，未证实开始或成功；仍按人类将领计算',['反派','阶段性对立者'],'完成国家秘密实验并维护组织利益，愿把献身看作忠诚证明','根据对象调整谈法，面对卫斯理以异常坦白打破敌意','计划受阻时寻求新执行者，也可能把对方的讥讽接受为自己应承担的使命','把组织需要放在个人同意之上，是其能献身也能要求他人牺牲的同一根源',[ab('秘密科研项目管理','组织长期人体试验、数据接收和保密行动','科研成果由团队和设备产生；他不能自行读取已记录思想'),ab('谈判与权力关系','熟悉官僚控制结构，能改变谈话风格争取合作','坦率可能是策略，无法保证对方信任或自愿赴死')],[ev('144',892,950,'真实职权、话术与组织观念'),ev('144',1200,1239,'秘密实验的具体机制和失败边界'),ev('144',1297,1346,'牺牲要求及愿亲自尝试的未完成结局')],profile='expert',aliases=['言王将军','言王上将']);cards.append(c)
for c in cards:
    if c['id']=='weisili_yan_wang':
        c['biography']+='他还显示出跃起抓住疾飞伯劳的出色身手，并在卫斯理将触摸剧毒窃听片时急声警告，救下处于对立面的来客；这使他的组织忠诚与具体善意形成不能简单抹平的矛盾。'
        c['abilities'].append(ab('敏捷扑取与危急救护','跃起在空中同时抓住两只疾飞伯劳，能迅速判断危险并警告对手','这是短距离反应和身手，不能换算超音速或普遍抗毒；接触剧毒物件需专用手套'))
        c['evidence'].append(ev('144',1055,1115,'抓鸟、警告剧毒圆片救卫斯理与保护手套'))
        c['baseline']['destruction']='训练有素的人类近身动作，未演示大范围破坏；剧毒窃听片是需手套的外物。'
        c['baseline']['speed']='可以短程跃起抓取疾飞伯劳，反应与动作出色；不外推精确速度。'
        c['logic']['triggers'].append({'situation':'对立者即将碰到自己知道的致命危险','condition':'危险迫在眉睫且对方尚不知情','action':'可能先急声警告救人，再面对任务机密可能泄漏的后果。'})
        rate(c,[4,0,1,4,3,7],neg=(1,1,1),tier='强',reason='直接展示短程跃起抓取疾飞伯劳及危急反应，按精于行动的人类计算；组织科技不作为本人虚拟化能力。')
save(cards)

